package com.bank.dsa;

import java.util.logging.*;

// Runnable demo: validate that a hashing/key parameter is prime.
public class CheckPrimeDemo {
    private static final Logger log = Logger.getLogger(CheckPrimeDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PrimeChecker checker = new PrimeChecker();

        for (int candidate : new int[]{7, 9}) {
            boolean prime = checker.isPrime(candidate);
            log.info(() -> "Parameter " + candidate + " prime? " + (prime ? "Yes" : "No"));
        }
    }
}

